   401→func (c *Checker) checkCallExpression(call *ast.CallExpression) Type {
   402→	fnType := c.checkExpression(call.Function)
   403→
   404→	if ft, ok := fnType.(*FunctionType); ok {
   405→		// Check argument count
   406→		if len(call.Arguments) != len(ft.ParamTypes) {
   407→			c.addError(0, 0, fmt.Sprintf(
   408→				"function expects %d arguments, got %d",
   409→				len(ft.ParamTypes), len(call.Arguments),
   410→			))
   411→		}
   412→
   413→		// Check argument types
   414→		for i, arg := range call.Arguments {
   415→			if i < len(ft.ParamTypes) {
   416→				argType := c.checkExpression(arg)
   417→				expectedType := ft.ParamTypes[i]
   418→				if !argType.Equal(expectedType) {
   419→					c.addError(0, 0, fmt.Sprintf(
   420→						"argument %d: expected %s, got %s",
   421→						i, expectedType.TypeString(), argType.TypeString(),
   422→					))
   423→				}
   424→			}
   425→		}
   426→
   427→		return ft.ReturnType
   428→	}
   429→
   430→	c.addError(0, 0, "cannot call non-function")
   431→	return &PrimitiveType{Name: "none"}
   432→}
   433→
   434→func (c *Checker) checkArrayExpression(arr *ast.ArrayExpression) Type {
   435→	if len(arr.Elements) == 0 {
   436→		// Empty array - type is ambiguous
   437→		return &ArrayType{ElementType: &PrimitiveType{Name: "unknown"}}
   438→	}
   439→
   440→	firstType := c.checkExpression(arr.Elements[0])
   441→
   442→	// Check all elements have same type
   443→	for i := 1; i < len(arr.Elements); i++ {
   444→		elemType := c.checkExpression(arr.Elements[i])
   445→		if !elemType.Equal(firstType) {
   446→			c.addError(0, 0, fmt.Sprintf(
   447→				"array element %d: expected %s, got %s",
   448→				i, firstType.TypeString(), elemType.TypeString(),
   449→			))
   450→		}
   451→	}
   452→
   453→	return &ArrayType{ElementType: firstType}
   454→}
   455→
   456→func (c *Checker) checkFieldExpression(field *ast.FieldExpression) Type {
   457→	exprType := c.checkExpression(field.Object)
   458→
   459→	if st, ok := exprType.(*StructType); ok {
   460→		if fieldType, ok := st.Fields[field.Field]; ok {
   461→			return fieldType
   462→		}
   463→		c.addError(0, 0, fmt.Sprintf("struct %s has no field %s", st.Name, field.Field))
   464→		return &PrimitiveType{Name: "unknown"}
   465→	}
   466→
   467→	c.addError(0, 0, fmt.Sprintf("cannot access field on %s", exprType.TypeString()))
   468→	return &PrimitiveType{Name: "none"}
   469→}
   470→
   471→func (c *Checker) checkIndexExpression(index *ast.IndexExpression) Type {
   472→	exprType := c.checkExpression(index.Object)
   473→	indexType := c.checkExpression(index.Index)
   474→
   475→	// Index must be numeric
   476→	if !c.isNumeric(indexType) {
   477→		c.addError(0, 0, "array index must be numeric")
   478→	}
   479→
   480→	if at, ok := exprType.(*ArrayType); ok {
   481→		return at.ElementType
   482→	}
   483→
   484→	c.addError(0, 0, fmt.Sprintf("cannot index %s", exprType.TypeString()))
   485→	return &PrimitiveType{Name: "none"}
   486→}
   487→
   488→func (c *Checker) checkIfExpression(ifExpr *ast.IfExpression) Type {
   489→	condType := c.checkExpression(ifExpr.Condition)
   490→
   491→	if !condType.Equal(&PrimitiveType{Name: "bool"}) {
   492→		c.addError(0, 0, "if condition must be bool")
   493→	}
   494→
   495→	thenType := c.checkExpression(ifExpr.ThenExpr)
   496→
   497→	if ifExpr.ElseExpr != nil {
   498→		elseType := c.checkExpression(ifExpr.ElseExpr)
   499→		if !thenType.Equal(elseType) {
   500→			c.addError(0, 0, fmt.Sprintf(
   501→				"if/else branch types mismatch: %s vs %s",
   502→				thenType.TypeString(), elseType.TypeString(),
   503→			))
   504→		}
   505→		return thenType
   506→	}
   507→
   508→	return thenType
   509→}
   510→
   511→func (c *Checker) checkMatchExpression(match *ast.MatchExpression) Type {
   512→	_ = c.checkExpression(match.Expression)
   513→
   514→	if len(match.Arms) == 0 {
   515→		return &PrimitiveType{Name: "none"}
   516→	}
   517→
   518→	var firstType Type
   519→	for i, arm := range match.Arms {
   520→		armType := c.checkExpression(arm.Value)
   521→		if i == 0 {
   522→			firstType = armType
   523→		} else if !armType.Equal(firstType) {
   524→			c.addError(0, 0, fmt.Sprintf(
   525→				"match arm %d: expected %s, got %s",
   526→				i, firstType.TypeString(), armType.TypeString(),
   527→			))
   528→		}
   529→	}
   530→
   531→	if firstType == nil {
   532→		return &PrimitiveType{Name: "none"}
   533→	}
   534→	return firstType
   535→}
   536→
   537→func (c *Checker) astTypeToCheckerType(t *ast.Type) Type {
   538→	if t == nil {
   539→		return &PrimitiveType{Name: "none"}
   540→	}
   541→
   542→	if t.IsArray {
   543→		return &ArrayType{ElementType: c.astTypeToCheckerType(t.ElementType)}
   544→	}
   545→
   546→	return &PrimitiveType{Name: t.Name}
   547→}
