/**
 * FV 소스 파일 + 외부 C 파일 → 바이너리 빌드 (FFI 지원)
 *
 * extern fn을 구현한 C 파일들을 함께 컴파일
 *
 * @param fvFile FV 소스 파일 경로
 * @param outFile 출력 바이너리 경로
 * @param cFiles 외부 C 파일 경로 배열
 */
buildWithExternC(fvFile: string, outFile: string, cFiles: string[]): void {
  if (!this.checkGCC()) {
    throw new Error(
      `❌ gcc/clang not found. Required for building .fv files.\n` +
      `   Install with: apt-get install build-essential (Debian/Ubuntu) or\n` +
      `                 brew install gcc (macOS) or\n` +
      `                 pkg install clang (Termux)`
    );
  }

  try {
    // Step 1: C 코드 생성
    console.log(`🔧 Compiling ${path.basename(fvFile)} to C...`);
    const cCode = this.compile(fvFile);

    // Step 2: 임시 C 파일 생성
    const timestamp = Date.now();
    const cFile = path.join(os.tmpdir(), `fv_build_${timestamp}.c`);
    fs.writeFileSync(cFile, cCode);

    // Step 3: 모든 C 파일 경로 확인
    const allCFiles = [cFile, ...cFiles];
    for (const cf of cFiles) {
      if (!fs.existsSync(cf)) {
        fs.unlinkSync(cFile);
        throw new Error(`❌ C file not found: ${cf}`);
      }
    }

    // Step 4: gcc로 빌드 (모든 C 파일 포함)
    console.log(`🏗️  Building binary: ${outFile}`);
    const gccCmd = `gcc -o ${outFile} ${allCFiles.join(' ')}`;
    try {
      execSync(gccCmd, { stdio: 'inherit' });
    } catch (error) {
      fs.unlinkSync(cFile);
      throw error;
    }

    // Step 5: 임시 C 파일 정리
    fs.unlinkSync(cFile);

    console.log(`✅ Build successful: ${outFile}`);
